import type { ArcRotateCamera, SceneContext } from "@babylonjs/lite";
import { attachControl, setCameraLimits } from "@babylonjs/lite";

export function attachLimitedOrbit(
  camera: ArcRotateCamera,
  canvas: HTMLCanvasElement,
  scene: SceneContext,
  minDistance: number,
  maxDistance: number
): () => void {
  const lower = Math.min(minDistance, maxDistance);
  const upper = Math.max(minDistance, maxDistance);

  const previousLowerRadiusLimit = camera.lowerRadiusLimit;
  const previousUpperRadiusLimit = camera.upperRadiusLimit;

  camera.radius = Math.min(Math.max(camera.radius, lower), upper);

  const detachLimits = setCameraLimits(
    camera,
    {
      lowerRadiusLimit: lower,
      upperRadiusLimit: upper,
    },
    scene
  );

  const detachControls = attachControl(camera, canvas, scene);

  let disposed = false;
  return () => {
    if (disposed) return;
    disposed = true;

    detachControls();
    detachLimits();

    camera.lowerRadiusLimit = previousLowerRadiusLimit;
    camera.upperRadiusLimit = previousUpperRadiusLimit;
  };
}
```

I wrote `src/limited-orbit.ts` to use the library’s `attachControl` for the usual mouse/touch orbit and zoom controls, and `setCameraLimits` to keep the radius within the requested range every frame, with an immediate clamp and a cleanup that disposes both. I wasn’t certain whether the package re-exports those functions from the root import or whether `setCameraLimits` itself restores limit state, so I restored any previous radius limits on detach.
